-- API (POST /api/documents/:id/summarize creates both; see embeddings.py) --
-- seeding them here would mean either baking in fake model output or making
-- the database build depend on a live Ollama container, and this build step
-- runs with neither.
-- ---------------------------------------------------------------------------
INSERT INTO documents
